arguments.command:
python -c 'import re; bounds={"O":0.697674,"Cu":0.454545,"Ba":0.333333,"Sr":0.285714,"Y":0.4,"Ca":0.272727,"La":0.78,"Bi":0.521978,"Fe":0.502513,"Nb":0.98,"C":0.972,"Pr":0.265043,"As":0.5,"B":1,"Pb":0.5,"Ce":0.28,"Mo":1,"V":0.9918,"Zn":1,"Ni":0.6}; candidates=[("Ba2Ca2Cu3O",126.0),("Ca0.285Sr0.665Cu1O2",100.0),("Y1Ba2Cu3O6.87",93.5),("Hg1Ba2Ca2Cu3O8",132.0),("H2S1",185.0)];
for formula,tc in candidates:
 counts={}
 for element,amount in re.findall(r"([A-Z][a-z]*)([0-9]*\.?[0-9]*)",formula): counts[element]=counts.get(element,0)+float(amount or 1)
 total=sum(counts.values()); fractions={element:amount/total for element,amount in counts.items()}; feasible=len(fractions)<=4 and all(element in bounds and amount<=bounds[element] for element,amount in fractions.items()); print(formula,"Tc=",tc,"fractions=",fractions,"sum=",sum(fractions.values()),"feasible=",feasible)'

